func axiomTypeError(entity string, value any, want string) error {
	return axiom.Error{Code: "AX503", Kind: "activity", Entity: entity, Message: fmt.Sprintf("type mismatch for %s: got %T, want %s", entity, value, want)}
}

func axiomToInt(value any) (int, bool) {
	switch v := value.(type) {
	case int:
		return v, true
	case int8:
		return int(v), true
	case int16:
		return int(v), true
	case int32:
		return int(v), true
	case int64:
		return int(v), true
	default:
		return 0, false
	}
}

func axiomToFloat(value any) (float64, bool) {
	switch v := value.(type) {
	case float32:
		return float64(v), true
	case float64:
		return v, true
	case int:
		return float64(v), true
	case int8:
		return float64(v), true
	case int16:
		return float64(v), true
	case int32:
		return float64(v), true
	case int64:
		return float64(v), true
	default:
		return 0, false
	}
}

func axiomToStringSlice(value any) ([]string, bool) {
	switch v := value.(type) {
	case []string:
		return v, true
	case []any:
		out := make([]string, len(v))
		for i, item := range v {
			converted, ok := item.(string)
			if !ok {
				return nil, false
			}
			out[i] = converted
		}
		return out, true
	default:
		return nil, false
	}
}

